create table if not exists raw_materials(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),sku text not null,name text not null,unit text not null default 'KG',cost_price numeric(14,2) default 0,active boolean default true,created_at timestamptz default now(),unique(tenant_id,sku));
create table if not exists boms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),finished_product_id uuid not null references products(id),version text not null,output_qty numeric(18,3) not null default 1,active boolean default true,created_at timestamptz default now());
create table if not exists bom_lines(id uuid primary key default gen_random_uuid(),bom_id uuid not null references boms(id) on delete cascade,raw_material_id uuid not null references raw_materials(id),quantity numeric(18,3) not null,wastage_pct numeric(5,2) default 0);
create table if not exists production_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),bom_id uuid not null references boms(id),warehouse_id uuid references warehouses(id),planned_qty numeric(18,3) not null,status text not null default 'planned',started_at timestamptz,completed_at timestamptz,created_at timestamptz default now());
create table if not exists production_consumption(id uuid primary key default gen_random_uuid(),production_order_id uuid not null references production_orders(id) on delete cascade,raw_material_id uuid not null references raw_materials(id),quantity numeric(18,3) not null);
create table if not exists finished_goods(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),production_order_id uuid references production_orders(id),product_id uuid not null references products(id),batch_no text,quantity numeric(18,3) not null,quality_status text default 'pending',created_at timestamptz default now());
